arguments.command:
git show 9830c6b955:CHANGELOG.md > /tmp/main_cl.md; python3 - <<'EOF'
def bullets(lines):
    out, cur = [], None
    for line in lines:
        if line.startswith('- '):
            if cur: out.append(''.join(cur))
            cur = [line]
        elif cur is not None:
            cur.append(line)
    if cur: out.append(''.join(cur))
    return [b.rstrip('\n') for b in out]

unrel = open('/tmp/main_cl.md').read().split('## Unreleased\n',1)[1].split('\n## ',1)[0]
target = [b for b in bullets(unrel.splitlines(keepends=True)) if 'gh-2471' in b.splitlines()[0]]
assert len(target) == 1, target
open('/tmp/bullet_2471.txt','w').write(target[0]+'\n')
print(f"bullet lines: {len(target[0].splitlines())}")
print(target[0].splitlines()[-1])
EOF

